function createBus() {
    const group = new THREE.Group();

    // Body
    const bodyGeo = new THREE.BoxGeometry(3.5, 1.4, 1.2);
    const bodyMat = new THREE.MeshLambertMaterial({ color: 0xFFCC00 });
    const body = new THREE.Mesh(bodyGeo, bodyMat);
    body.position.y = 0.7;
    body.castShadow = true;
