    // Glowing sign edge
    const glowGeo = new THREE.BoxGeometry(3.1, 0.9, 0.05);
    const glowMat = new THREE.MeshBasicMaterial({ color: shop.color, transparent: true, opacity: 0.3 });
    const glow = new THREE.Mesh(glowGeo, glowMat);
    glow.position.set(0, 4.2, 0.02);
    group.add(glow);

    // Door
    const doorGeo = new THREE.BoxGeometry(1, 2.5, 0.1);
    const doorMat = new THREE.MeshLambertMaterial({ color: 0x654321 });
